# Surah Al-Kahf (chapter 18) — part 8: ayat 71-80 (IDs 2211-2220)
SURAH = 18

ENTRIES = {
2211: (
"پس دونوں چل پڑے یہاں تک کہ جب دونوں کشتی میں سوار ہوئے تو اس نے اس میں شگاف کر دیا — موسیٰؑ نے کہا کیا آپ نے اس میں شگاف کیا تاکہ اس کے سواروں کو ڈبو دیں؟ آپ نے تو عجیب کام کیا",
"""۱۔ خضرؑ نے کشتی میں سوراخ کیا؛ موسیٰؑ کی سمجھ بوجھ — یہ تو ظلم ہے؛ دراصل اللہ کا راز تھا۔
۲۔ ’’فَانْطَلَقَا حَتَّىٰ إِذَا رَكِبَا فِي السَّفِينَۃِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْئًا إِمْرًا‘‘ — پس دونوں چل پڑے یہاں تک کہ جب دونوں کشتی میں سوار ہوئے تو اس نے اس میں شگاف کر دیا — موسیٰؑ نے کہا کیا آپ نے اس میں شگاف کیا تاکہ اس کے سواروں کو ڈبو دیں؟ آپ نے تو عجیب کام کیا — یعنی وہ دونوں چلتے رہے یہاں تک کہ کشتی میں سوار ہوئے تو اس نے کشتی میں سوراخ کر دیا — موسیٰؑ نے کہا کیا آپ نے اس لیے سوراخ کیا کہ اس کے سواروں کو ڈبو دیں؟ آپ نے تو بڑا خوفناک کام کیا۔
۳۔ عملی سبق: اللہ کے فیصلوں میں حکمت ہوتی ہے؛ جلدی فیصلہ نہ کرو۔"""
),
2212: (
"اس نے کہا کیا میں نے آپ سے نہیں کہا تھا کہ آپ میرے ساتھ صبر نہیں کر سکیں گے",
"""۱۔ خضرؑ نے یاد دلایا؛ آپؑ وعدہ بھول چکے تھے؛ صبر کی شرط کے توڑ۔
۲۔ ’’قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا‘‘ — اس نے کہا کیا میں نے آپ سے نہیں کہا تھا کہ آپ میرے ساتھ صبر نہیں کر سکیں گے — یعنی خضرؑ نے کہا کیا میں نے آپ سے نہیں کہا کہ آپ میرے ساتھ صبر نہیں کر سکتے۔
۳۔ عملی سبق: جو وعدہ کرو اسے پورا کرو؛ صبر اختیار کرو۔"""
),
2213: (
"موسیٰؑ نے کہا میری بھول پر مجھے نہ پکڑیں اور نہ میرے معاملے میں مجھے سختی دیں",
"""۱۔ موسیٰؑ نے معافی مانگی؛ خضرؑ سے نرم روی کی اپیل۔
۲۔ ’’قَالَ لَا تُؤَاخِذْنِي بِمَا نَسِيتُ وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا‘‘ — موسیٰؑ نے کہا میری بھول پر مجھے نہ پکڑیں اور نہ میرے معاملے میں مجھے سختی دیں — یعنی موسیٰؑ نے کہا میری بھول کے سبب مجھ سے بازپرس نہ کرو اور میرے معاملے میں مجھے سختی نہ دو۔
۳۔ عملی سبق: بھول جانے پر معافی مانگو؛ دوسروں کو معاف کرو۔"""
),
2214: (
"پس دونوں چل پڑے یہاں تک کہ انہیں ایک نوجوان ملا — انہوں نے اسے قتل کر دیا — موسیٰؑ نے کہا کیا آپ نے بے گناہ نفس کو بغیر کسی نفس کے بدلے قتل کیا؟ آپ نے تو بہت بڑا گناہ کیا",
"""۱۔ خضرؑ نے نوجوان کو قتل کیا؛ موسیٰؑ حیران؛ اللہ کے راز الگ ہیں۔
۲۔ ’’فَانْطَلَقَا حَتَّىٰ إِذَا لَقِيَا غُلَامًا فَقَتَلَهُ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّۃً بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْئًا نُّكْرًا‘‘ — پس دونوں چل پڑے یہاں تک کہ انہیں ایک نوجوان ملا — انہوں نے اسے قتل کر دیا — موسیٰؑ نے کہا کیا آپ نے بے گناہ نفس کو بغیر کسی نفس کے بدلے قتل کیا؟ آپ نے تو بہت بڑا گناہ کیا — یعنی وہ دونوں چلے یہاں تک کہ انہیں ایک نوجوان ملا اور انہوں نے اسے قتل کر دیا — موسیٰؑ نے کہا کیا آپ نے بے گناہ جان کو بغیر کسی جان کے بدلے قتل کیا؟ آپ نے تو بہت برا کام کیا۔
۳۔ عملی سبق: اللہ کے فیصلوں میں حکمت ہوتی ہے؛ جلدی فیصلہ نہ کرو؛ صبر اختیار کرو۔"""
),
2215: (
"اس نے کہا کیا میں نے آپ سے نہیں کہا کہ آپ میرے ساتھ صبر نہیں کر سکیں گے",
"""۱۔ خضرؑ نے دوبارہ یاد دلایا؛ آپؑ وعدہ بھول چکے تھے۔
۲۔ ’’قَالَ أَلَمْ أَقُلْ لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا‘‘ — اس نے کہا کیا میں نے آپ سے نہیں کہا کہ آپ میرے ساتھ صبر نہیں کر سکیں گے — یعنی خضرؑ نے کہا کیا میں نے آپ سے نہیں کہا کہ آپ میرے ساتھ صبر نہیں کر سکتے۔
۳۔ عملی سبق: ایڈوانس وارننگ کو بھلا نہ کرو؛ صبر اختیار کرو۔"""
),
2216: (
"موسیٰؑ نے کہا اگر میں اس کے بعد آپ سے کسی چیز کے بارے میں پوچھوں تو آپ مجھے اپنے ساتھ ساتھ نہ رکھیں — آپ یقیناً میری طرف سے معذرت تک پہنچ گئے ہیں",
"""۱۔ موسیٰؑ نے آخری تنبیہ دی؛ خضرؑ کو معذرت کرنی ہوگی؛ آپؑ اپنی غلطی کا اعتراف کرتے ہیں۔
۲۔ ’’قَالَ إِن سَأَلْتُكَ عَن شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِن لَّدُنِّي عُذْرًا‘‘ — موسیٰؑ نے کہا اگر میں اس کے بعد آپ سے کسی چیز کے بارے میں پوچھوں تو آپ مجھے اپنے ساتھ ساتھ نہ رکھیں — آپ یقیناً میری طرف سے معذرت تک پہنچ گئے ہیں — یعنی موسیٰؑ نے کہا اگر میں اس کے بعد آپ سے کسی چیز کے بارے میں پوچھوں تو آپ مجھے اپنے ساتھ نہ رکھیں — آپ میری طرف سے معذرت تک پہنچ چکے ہیں۔
۳۔ عملی سبق: اپنی غلطی کا اعتراف کرو؛ دوسروں کی گنجائش دو۔"""
),
2217: (
"پس دونوں چل پڑے یہاں تک کہ وہ ایک بستی کے لوگوں کے پاس آئے — انہوں نے اس بستی والوں سے کھانا مانگا — مگر انہوں نے ان دونوں کو مہمان بنانے سے انکار کر دیا — پس انہوں نے وہاں ایک دیوار دیکھی جو گرنے کے قریب تھی — پس اس نے اسے کھڑا کر دیا — موسیٰؑ نے کہا اگر آپ چاہتے تو اس پر کچھ اجرت لے لیتے",
"""۱۔ خضرؑ اور موسیٰؑ بستی میں؛ مہمان نوازی کا انکار؛ دیوار کھڑی کی؛ اجرت نہ مانگی۔
۲۔ ’’فَانْطَلَقَا حَتَّىٰ إِذَا أَتَيَا أَهْلَ قَرْيَۃٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُ قَالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا‘‘ — پس دونوں چل پڑے یہاں تک کہ وہ ایک بستی کے لوگوں کے پاس آئے — انہوں نے اس بستی والوں سے کھانا مانگا — مگر انہوں نے ان دونوں کو مہمان بنانے سے انکار کر دیا — پس انہوں نے وہاں ایک دیوار دیکھی جو گرنے کے قریب تھی — پس اس نے اسے کھڑا کر دیا — موسیٰؑ نے کہا اگر آپ چاہتے تو اس پر کچھ اجرت لے لیتے — یعنی وہ دونوں چلے یہاں تک کہ وہ ایک بستی کے لوگوں کے پاس پہنچے — انہوں نے وہاں کے لوگوں سے کھانا مانگا مگر انہوں نے ان کی مہمان نوازی کرنے سے انکار کر دیا — وہاں انہوں نے ایک دیوار دیکھی جو گرنے والی تھی پس اس نے اسے کھڑا کر دیا — موسیٰؑ نے کہا اگر آپ چاہتے تو اس پر کچھ اجرت لے سکتے تھے۔
۳۔ عملی سبق: بغیر اجرت کے نیکی کرو؛ اللہ سے اجر مانگو۔"""
),
2218: (
"اس نے کہا یہ میرے اور آپ کے درمیان علیحدگی ہے — میں آپ کو اس کی تفصیل بتاؤں گا جو آپ صبر نہ کر سکے",
"""۱۔ خضرؑ نے موسیٰؑ کو سارے راز کی حقیقت بتانے کا اعلان کیا۔
۲۔ ’’قَالَ هَٰذَا فِرَاقُ بَيْنِي وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا‘‘ — اس نے کہا یہ میرے اور آپ کے درمیان علیحدگی ہے — میں آپ کو اس کی تفصیل بتاؤں گا جو آپ صبر نہ کر سکے — یعنی خضرؑ نے کہا یہ میرے اور آپ کے درمیان جدائی کا وقت ہے اور میں آپ کو ان چیزوں کی تفصیل بتاؤں گا جن پر آپ صبر نہ کر سکتے تھے۔
۳۔ عملی سبق: حقیقت کاعلم — اللہ کے اختیار میں ہے؛ صبر کرو۔"""
),
2219: (
"رہی وہ کشتی تو وہ کچھ مسکینوں کی تھی جو سمندر میں کام کرتے تھے — پس میں نے چاہا کہ اسے خراب کر دیں — اور ان کے پیچھے ایک بادشاہ ہے جو ہر کشتی کو زبردستی چھین لیتا ہے",
"""۱۔ خضرؑ کا پہلا راز — کشتی غریبوں کی تھی؛ بادشاہ زبردستی چھین لیتا ہے؛ سوراخ کرنے سے کشتی بچ گئی۔
۲۔ ’’أَمَّا السَّفِينَۃُ فَكَانَتْ لِمَسَاكِينَ يَعْمَلُونَ فِي الْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَاءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَۃٍ غَصْبًا‘‘ — رہی وہ کشتی تو وہ کچھ مسکینوں کی تھی جو سمندر میں کام کرتے تھے — پس میں نے چاہا کہ اسے خراب کر دیں — اور ان کے پیچھے ایک بادشاہ ہے جو ہر کشتی کو زبردستی چھین لیتا ہے — یعنی وہ کشتی کچھ مسکینوں کی تھی جو سمندر میں کام کرتے تھے پس میں نے چاہا کہ اسے عیب دار کر دوں اور ان کے پیچھے ایک بادشاہ ہے جو ہر کشتی کو زبردستی چھین لیتا ہے۔
۳۔ عملی سبق: اللہ کی حفاظت اپنی نظروں سے نظر نہیں آتی؛ اس کے فیصلوں پر بھروسہ کرو۔"""
),
2220: (
"اور رہا وہ نوجوان تو اس کے ماں باپ مؤمن تھے — پس ہم ڈرے کہ وہ انہیں سرکشی اور کفر میں مبتلا کر دے گا",
"""۱۔ خضرؑ کا دوسرا راز — ماں باپ مؤمن؛ نوجوان کافر بن جاتا؛ اس لیے اسے قتل کیا گیا۔
۲۔ ’’وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَا أَن يُرْهِقَهُمَا طُغْيَانًا وَكُفْرًا‘‘ — اور رہا وہ نوجوان تو اس کے ماں باپ مؤمن تھے — پس ہم ڈرے کہ وہ انہیں سرکشی اور کفر میں مبتلا کر دے گا — یعنی وہ نوجوان جس کے ماں باپ مؤمن تھے پس ہم ڈر گئے کہ وہ انہیں ظلم اور کفر میں مبتلا کر دے گا۔
۳۔ عملی سبق: اللہ کا علم لامحدود ہے؛ انسان کو تھوڑا علم دیا گیا ہے؛ اس کے فیصلوں پر ایمان لاؤ۔"""
),
}
